    const sky = dark ? (sc.nsky || ['#0E1730', '#26365E']) : (sc.sky || ['#DCE6F2', '#F4F1EA']);
    const clear = P.clear === true || P.clear === 'true';
    if (clear) sc.kit = true;
    const skyBg = sc.kit ? 'transparent' : 'linear-gradient(180deg, ' + sky[0] + ' 0%, ' + sky[1] + ' 100%)';
    const fogBg = (sc.kit || noFog) ? 'none' : 'linear-gradient(0deg, ' + this.css(haze, Math.min(0.6, fogA * 1.1)) + ' 0%, ' + this.css(haze, 0) + ' 42%)';
    const os = Math.min(W, H) * (dark ? 0.12 : 0.3);
