    const stars = [];
    if (dark && sc.stars && !sc.kit) { for (let i = 0; i < 46; i++) stars.push({ l: ((i * 73) % 97) / 97 * W, t: ((i * 37) % 53) / 53 * H * 0.5, s: 1.5 + (i % 3), o: 0.35 + (i % 5) * 0.12, dl: (i % 7) * 0.6 }); }
